    if argv[0] in ("-h","--help"):
        sys.stderr.write("Usage: taplo [OPTIONS] <COMMAND>\n\nCommands:\n  lint         Lint TOML documents [aliases: check, validate]\n  format       Format TOML documents [aliases: fmt]\n  lsp          Language server operations\n  config       Operations with the Taplo config file [aliases: cfg]\n  get          Extract a value from the given TOML document\n  toml-test    Start a decoder for `toml-test`\n  completions  Generate completions\n\nOptions: --colors <COLORS> --verbose --log-spans -h --help -V --version\n")
        return 0
    if argv[0] == "help":
        return _format(["--help"])
    if argv[0] in ("-V","--version"):
