"""Query and serialize TOML values for the get command."""
import fnmatch
import json
import re
import sys

from tomltest import _parse


def _path_parts(pattern):
    parts = []
    for part in re.findall(r"[^.\[\]]+|\[[^\]]*\]", pattern):
        if part.startswith("["):
            inside = part[1:-1]
            parts.append("*" if inside in ("", "*") else inside)
        else:
            parts.append(part)
    return parts


def _select(value, parts):
    if not parts:
        return [value]
    head, tail = parts[0], parts[1:]
    selected = []
    if isinstance(value, dict):
        for key, child in value.items():
            if head == "*" or fnmatch.fnmatchcase(str(key), head):
                selected.extend(_select(child, tail))
    elif isinstance(value, list):
        if head == "*":
            for child in value:
                selected.extend(_select(child, tail))
        else:
            try:
                index = int(head)
                if index < 0:
                    index += len(value)
                if 0 <= index < len(value):
                    selected.extend(_select(value[index], tail))
            except ValueError:
                pass
    return selected


def _toml_string(value):
    return json.dumps(value, ensure_ascii=False)


def _toml(value, indent=0):
    if isinstance(value, bool): return "true" if value else "false"
    if isinstance(value, str): return _toml_string(value)
    if value is None: return ""
    if isinstance(value, list): return "[ " + ", ".join(_toml(v, indent) for v in value) + " ]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{k} = {_toml(value[k], indent)}" for k in sorted(value)) + " }"
    return str(value)


def _is_inline_table(source, pattern):
    if not pattern:
        return False
    key = pattern.rsplit(".", 1)[-1]
    if key.endswith("]"):
        return False
    return re.search(r"(?m)^\s*" + re.escape(key) + r"\s*=\s*\{", source) is not None


def _text(value, separator="\n"):
    if isinstance(value, bool): return str(value).lower()
    if isinstance(value, str): return value
    if isinstance(value, (int, float)): return str(value)
    if isinstance(value, list):
        if any(isinstance(x, (dict, list)) for x in value):
            raise ValueError
        return separator.join(_text(x, separator) for x in value)
    raise ValueError


def run(args):
    path = None
    output = "value"
    separator = "\n"
    strip_newline = False
    positional = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-h", "--help"):
            return 0
        if arg in ("-f", "--file-path", "-o", "--output-format", "--separator"):
            i += 1
            if i >= len(args): return 2
            if arg in ("-f", "--file-path"): path = args[i]
            elif arg in ("-o", "--output-format"): output = args[i]
            else: separator = args[i]
        elif arg.startswith("--file-path="): path = arg.split("=", 1)[1]
        elif arg.startswith("--output-format="): output = arg.split("=", 1)[1]
        elif arg.startswith("--separator="): separator = arg.split("=", 1)[1]
        elif arg == "-s" or arg == "--strip-newline": strip_newline = True
        elif arg.startswith("-") and arg != "-":
            if arg in ("--colors",):
                i += 1
            elif arg in ("--verbose", "--log-spans"):
                pass
            else:
                return 2
        else: positional.append(arg)
        i += 1
    if output not in ("value", "json", "toml"):
        print(f"error: invalid value '{output}' for '--output-format <OUTPUT_FORMAT>'\n\n  [possible values: value, json, toml]\n\nFor more information, try '--help'.", file=sys.stderr)
        return 2
    if separator != "\n" and output != "value": return 1
    pattern = positional[0] if positional else None
    if len(positional) > 1: return 2
    try:
        src = open(path, encoding="utf-8").read() if path else sys.stdin.read()
        document = _parse(src)
        values = [document] if pattern is None else _select(document, _path_parts(pattern))
        if not values: return 1
        if output == "json":
            rendered = json.dumps(values[0] if len(values) == 1 else values, ensure_ascii=False, indent=2) + "\n"
        elif output == "toml":
            val = values[0] if len(values) == 1 else values
            if isinstance(val, dict) and not _is_inline_table(src, pattern):
                rendered = "\n".join(f"{k} = {_toml(val[k])}" for k in sorted(val)) + "\n"
            else:
                rendered = _toml(val) + "\n"
        else:
            rendered = separator.join(_text(v, separator) for v in values) + "\n"
        sys.stdout.write(rendered[:-1] if strip_newline and rendered.endswith("\n") else rendered)
        return 0
    except Exception:
        return 1

"""Implementation of Taplo's toml-test decoder output format."""
import datetime
import ast
import json
import re
from typing import Any


class _TomlFloat(float):
    def __new__(cls, value: float, spelling: str):
        obj = super().__new__(cls, value)
        obj.spelling = spelling
        return obj


def _encode(value: Any, dates: list[str]) -> Any:
    if isinstance(value, dict):
        return {key: _encode(item, dates) for key, item in value.items()}
    if isinstance(value, list):
        return [_encode(item, dates) for item in value]
    if isinstance(value, bool):
        return {"type": "bool", "value": "true" if value else "false"}
    if isinstance(value, int):
        return {"type": "integer", "value": str(value)}
    if isinstance(value, float):
        # Rust's float display keeps integral floats distinguishable.
        rendered = getattr(value, "spelling", repr(value))
        if rendered.lower() in ("+nan", "-nan"):
            rendered = "nan"
        elif rendered.lower() not in ("inf", "+inf", "-inf", "nan") and "e" not in rendered.lower() and "." not in rendered:
            rendered += ".0"
        return {"type": "float", "value": rendered}
    if isinstance(value, str):
        return {"type": "string", "value": value}
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        raw = dates.pop(0) if dates else value.isoformat()
        kind = ("datetime" if value.tzinfo is not None else "datetime-local") if isinstance(value, datetime.datetime) else (
            "date-local" if isinstance(value, datetime.date) else "time-local"
        )
        return {"type": kind, "value": '"' + raw + '"'}
    return value


def decode(source: str) -> str:
    """Parse TOML and return its compact toml-test JSON representation."""
    parsed = _parse(source)
    # tomllib normalizes offsets (notably Z into +00:00); preserve TOML's
    # original date/time spelling for the tagged string representation.
    dt_re = re.compile(r"(?<![\w\"'])\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?)?(?![\w'])|(?<![\w'])\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?(?![\w'])")
    dates = [m.group(0) for m in dt_re.finditer(source)]
    return json.dumps(_encode(parsed, dates), ensure_ascii=False, separators=(",", ":"))


def _parse(source: str) -> dict:
    """Small TOML parser for Python 3.10, where tomllib is not available."""
    root: dict = {}
    table = root
    array_table: list | None = None
    pending = ""
    for raw in source.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        pending = (pending + "\n" + line).strip() if pending else line
        if _unclosed(pending):
            continue
        line, pending = pending, ""
        if line.startswith("[[") and line.endswith("]]" ):
            path = _key_parts(line[2:-2])
            table = root
            for part in path[:-1]:
                table = table.setdefault(part, {})
            array_table = table.setdefault(path[-1], [])
            item = {}
            array_table.append(item)
            table = item
            continue
        if line.startswith("[") and line.endswith("]"):
            path = _key_parts(line[1:-1])
            table = root
            for part in path:
                next_table = table.setdefault(part, {})
                if isinstance(next_table, list):
                    next_table = next_table[-1]
                table = next_table
            continue
        eq = _find_eq(line)
        if eq < 0:
            continue
        key = _key_parts(line[:eq].strip())
        val = _value(_strip_comment(line[eq + 1:].strip()))
        target = table
        for part in key[:-1]:
            child = target.setdefault(part, {})
            if isinstance(child, list):
                child = child[-1]
            target = child
        target[key[-1]] = val
    return root


def _key_parts(source: str) -> list[str]:
    """Split dotted TOML keys while preserving dots inside quoted keys."""
    parts = []
    start = 0
    quote = None
    escaped = False
    for i, char in enumerate(source):
        if quote:
            if escaped:
                escaped = False
            elif char == "\\" and quote == '"':
                escaped = True
            elif char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == ".":
            parts.append(source[start:i].strip())
            start = i + 1
    parts.append(source[start:].strip())
    result = []
    for part in parts:
        part = part.strip()
        if len(part) >= 2 and part[0] == part[-1] and part[0] in "\"'":
            part = part[1:-1]
        result.append(part)
    return result


def _unclosed(s: str) -> bool:
    if s.count('"""') % 2 or s.count("'''") % 2:
        return True
    if '"""' in s or "'''" in s:
        return False
    q = None; esc = False; depth = 0
    for c in s:
        if q:
            if esc: esc = False
            elif c == "\\" and q == '"': esc = True
            elif c == q: q = None
        elif c in "\"'": q = c
        elif c in "[{": depth += 1
        elif c in "]}": depth -= 1
    return bool(q or depth > 0)


def _find_eq(s: str) -> int:
    q = None; esc = False; depth = 0
    for i, c in enumerate(s):
        if q:
            if esc: esc = False
            elif c == "\\" and q == '"': esc = True
            elif c == q: q = None
        elif c in "\"'": q = c
        elif c in "[{": depth += 1
        elif c in "]}": depth -= 1
        elif c == "=" and depth == 0: return i
    return -1

